{
  "titre": "Les Trente Glorieuses : révisions autonomes",
  "objectifGeneral": "Consolider les connaissances sur la période des Trente Glorieuses en identifiant ses caractéristiques majeures et ses limites.",
  "notionsPivots": [
    "la croissance économique",
    "les transformations sociales",
    "la société de consommation",
    "l'État-providence",
    "la tertiarisation de l'emploi",
    "la crise pétrolière de 1973"
  ],
  "etapes": [
    {
      "titre": "Situer et définir les Trente Glorieuses",
      "objectif": "Repérer les bornes chronologiques et les concepts clés de la période",
      "cartes": [
        {
          "titre": "Frise des Trente Glorieuses",
          "objectif": "Ordonner des événements marquants",
          "module": "SortParagraphs",
          "palier": "decouverte",
          "duree": 10,
          "consigne": "Replace dans l'ordre chronologique les événements suivants en les glissant-déposant : début des Trente Glorieuses, crise pétrolière de 1973, création de la Sécurité sociale, Baby-boom, plan Marshall, fin des Trente Glorieuses en France."
        }
      ]
    },
    {
      "titre": "Comprendre les facteurs de la croissance",
      "objectif": "Identifier les causes et conséquences économiques et sociales",
      "cartes": [
        {
          "titre": "Vocabulaire des Trente Glorieuses",
          "objectif": "Associer des termes à leur définition",
          "module": "Appariement",
          "palier": "entrainement",
          "duree": 15,
          "consigne": "Relie chaque terme à sa définition en faisant glisser les étiquettes vers les bonnes réponses : 'société de consommation', 'état-providence', 'tertiarisation', 'croissance économique', 'Baby-boom'."
        }
      ]
    },
    {
      "titre": "Évaluer ses connaissances",
      "objectif": "Vérifier la maîtrise des notions et des dates",
      "cartes": [
        {
          "titre": "Quiz de révision",
          "objectif": "Répondre à des questions précises sur la période",
          "module": "QuizSetQCM",
          "palier": "transfert",
          "duree": 15,
          "consigne": "Réponds aux 5 questions à choix multiples sur les Trente Glorieuses pour tester tes connaissances. Tu recevras un bilan à la fin."
        }
      ]
    },
    {
      "titre": "Analyser une source",
      "objectif": "Interpréter un document historique pour en tirer des informations",
      "cartes": [
        {
          "titre": "Texte source : la société de consommation",
          "objectif": "Comprendre et expliquer un extrait",
          "module": "FillInTheBlanks",
          "palier": "transfert",
          "duree": 10,
          "consigne": "Remplis les trous dans le texte à l'aide des mots proposés pour reconstituer un extrait sur la société de consommation pendant les Trente Glorieuses."
        }
      ]
    }
  ]
}
